--PROTECTED BY ANKRO
local _B=bit32
if type(_B)~="table" then error("Unsupported executor: bit32 required") end
local function _u32(x) return _B.band(x,0xffffffff) end
local function _rol(x,n) return _B.bor(_B.lshift(x,n),_B.rshift(x,32-n)) end
local function _w(a,b,c,d) return a+b*256+c*65536+d*16777216 end

local function _chacha(kb,nb,data)
    local k={}
    for i=1,8 do
        local j=(i-1)*4+1
        k[i]=_w(kb[j],kb[j+1],kb[j+2],kb[j+3])
    end
    local n={}
    for i=1,3 do
        local j=(i-1)*4+1
        n[i]=_w(nb[j],nb[j+1],nb[j+2],nb[j+3])
    end
    local st={
        0x61707865,0x3320646e,0x79622d32,0x6b206574,
        k[1],k[2],k[3],k[4],k[5],k[6],k[7],k[8],
        1,n[1],n[2],n[3]
    }
    local out={}
    local counter=1
    for pos=1,#data,64 do
        local x={table.unpack(st)}
        x[13]=counter
        local function Q(a,b,c,d)
            x[a]=_u32(x[a]+x[b]); x[d]=_rol(_B.bxor(x[d],x[a]),16)
            x[c]=_u32(x[c]+x[d]); x[b]=_rol(_B.bxor(x[b],x[c]),12)
            x[a]=_u32(x[a]+x[b]); x[d]=_rol(_B.bxor(x[d],x[a]),8)
            x[c]=_u32(x[c]+x[d]); x[b]=_rol(_B.bxor(x[b],x[c]),7)
        end
        for _=1,10 do
            Q(1,5,9,13); Q(2,6,10,14); Q(3,7,11,15); Q(4,8,12,16)
            Q(1,6,11,16); Q(2,7,12,13); Q(3,8,9,14); Q(4,5,10,15)
        end
        local block={}
        for j=1,16 do
            local v=_u32(x[j]+st[j])
            block[#block+1]=string.char(_B.band(v,255),_B.band(_B.rshift(v,8),255),_B.band(_B.rshift(v,16),255),_B.band(_B.rshift(v,24),255))
        end
        local take=math.min(64,#data-pos+1)
        local part=data:sub(pos,pos+take-1)
        for j=1,take do
            out[#out+1]=string.char(_B.bxor(part:byte(j),block[j]:byte()))
        end
        counter=counter+1
    end
    return table.concat(out)
end

